const componentData = window.POEMUI_COMPONENT_DATA;
const styleUtilitiesData = window.POEMUI_STYLE_UTILITIES;
const releaseNotesData = window.POEMUI_RELEASE_NOTES;

if (!componentData) {
  throw new Error('PoemUI component catalog is missing. Run npm run site:build.');
}
if (!styleUtilitiesData || !Array.isArray(styleUtilitiesData.items) || styleUtilitiesData.items.length !== 562) {
  throw new Error('PoemUI Style Utilities preview schema is missing. Run npm run styles:catalog:generate.');
}
if (!releaseNotesData || !Array.isArray(releaseNotesData.announcements) || !releaseNotesData.announcements.length) {
  throw new Error('PoemUI release notes data is missing. Run npm run release-notes:generate.');
}

const groups = componentData.groups;
const packageComponents = componentData.packageComponents;
const componentSummaries = componentData.componentSummaries || {};
const starterUsageByComponent = componentData.starterUsage || {};
const colorTokenData = componentData.colorTokens || { light: {}, dark: {} };
const CURATED_UTILITY_HUES = ['red', 'orange', 'amber', 'emerald', 'teal', 'blue', 'violet', 'pink'];
const CURATED_UTILITY_TEXT_CLASSES = CURATED_UTILITY_HUES.map((hue) => `pui-text-${hue}`);
const CURATED_UTILITY_SURFACE_CLASSES = CURATED_UTILITY_HUES.flatMap((hue) => [
  `pui-bg-${hue}`,
  `pui-bg-${hue}-soft`,
  `pui-border-${hue}`,
]);
const CURATED_UTILITY_COLOR_TOKENS = CURATED_UTILITY_HUES.flatMap((hue) => [
  `--pui-color-${hue}`,
  `--pui-color-${hue}-solid`,
  `--pui-color-${hue}-soft`,
]);
const typographyTokenData = componentData.typographyTokens || {};
const spacingTokenData = componentData.spacingTokens || {};
const previewWorkspaceAsset = './assets/poemui-workspace.png';
const avatarRealProfileSource = 'https://lg-1sobdtqg-1254094290.cos.ap-shanghai.myqcloud.com/user_img/QX_girl.png';

const iconData = window.POEMUI_ICON_DATA || { categories: [], icons: [] };
const styleUtilityPreviewByName = new Map(styleUtilitiesData.items.map((item) => [item.name, item]));
const releaseNotesGroup = groups.find((group) => group.key === 'getting-started') || {
  key: 'getting-started',
  title: '开始与规范',
};
const releaseNotesItem = {
  id: 'release-notes',
  name: 'Updates 更新公告',
  nameEn: 'Updates',
  nameZh: '更新公告',
  kind: 'document',
  status: 'published',
  group: releaseNotesGroup,
};
const allItems = groups
  .flatMap((group) => group.items.map((item) => ({ ...item, group })))
  .concat(releaseNotesItem);
const feedbackOrdinalById = new Map(allItems.map((item, index) => [item.id, String(index + 1).padStart(2, '0')]));

function catalogItemFor(id) {
  return allItems.find((item) => item.id === id);
}

function feedbackOrdinalFor(id) {
  return feedbackOrdinalById.get(id) || '';
}

function previewIdFor(id) {
  const item = catalogItemFor(id);
  return item && item.previewId ? item.previewId : id;
}

const edgeToEdgePreviewIds = new Set([
  'action-sheet',
  'date-time-picker',
  'dialog',
  'dropdown-menu',
  'navbar',
  'overlay',
  'picker',
  'popover',
  'popup',
  'sheet',
  'sidebar',
  'sticky',
  'tabbar',
  'toast',
  'dynamic-message',
  'tour',
]);

function shadcnEntryFor(id) {
  const item = catalogItemFor(id);
  if (!item || !item.shadcnStatus) return null;
  return {
    source: item.name,
    status: item.shadcnStatus,
    trigger: item.trigger,
    note: item.note,
  };
}

