function makeApiProps(id) {
  return (apiPropsByComponent[id] || []).map((key) => {
    const definition = releasePropDefinitions[id] && releasePropDefinitions[id][key];
    return definition ? { key, label: key, ...definition } : makePropDefinition(key, id);
  });
}

function makePropDefinition(key, id) {
  if (key === 'placeholder' && ['navbar', 'tabbar'].includes(id)) {
    return { key, label: key, type: 'boolean', value: false };
  }
  const componentDefaults = componentPropDefaults[id] || {};
  const defaultValue = Object.prototype.hasOwnProperty.call(componentDefaults, key) ? componentDefaults[key] : propDefaultValues[key];
  if (propPresets[key]) {
    return { key, label: key, type: 'select', value: defaultValue || propPresets[key][0], options: propPresets[key] };
  }
  if (booleanProps.has(key)) {
    const onByDefault = ['visible', 'showOverlay', 'safeAreaInsetBottom', 'safeAreaInsetTop', 'bordered', 'indicator', 'addBtn', 'removeBtn', 'preview', 'autoClose', 'usePopup', 'showHeader', 'showLeftCheck', 'showLeftSecond', 'showRightFirst', 'showClose'].includes(key);
    return { key, label: key, type: 'boolean', value: typeof defaultValue === 'boolean' ? defaultValue : onByDefault };
  }
  if (rangeDefaults[key] && !['input', 'textarea', 'search', 'input-otp', 'select'].includes(id)) {
    const def = rangeDefaults[key];
    return { key, label: key, type: 'range', value: def[0], min: def[1], max: def[2] };
  }
  if (objectDefaults[key]) {
    return { key, label: key, type: 'json', value: objectDefaults[key] };
  }
  const textDefaults = {
    title: id === 'popup' ? '弹出层' : id ? createName(id) : '标题',
    content: id === 'popup' ? '弹出层正文区域可承载表单、列表、详情或确认操作。' : '内容',
    text: '文本',
    message: '操作已完成',
    description: '组件说明内容',
    subtitle: id === 'popup' ? '允许在标题下方展示次级标题' : '次级标题',
    value: 'PoemUI',
    prefix: '',
    suffix: '',
    ratio: '16 / 9',
    placeholder: '请输入',
    label: '标签',
    note: '补充说明',
    tips: '提示文本',
    cancelBtn: '取消',
    confirmBtn: '确认',
    cancelText: '取消',
    openType: '',
    hoverClass: 'pui-button--hover',
    format: 'YYYY-MM-DD',
    start: '2026-01-01',
    end: '2026-12-31',
    time: '3661000',
    backgroundColor: 'rgba(0,0,0,0.38)',
    color: '#111217',
    src: '',
    image: '',
    icon: '',
    leftAction1Icon: 'check',
    leftAction2Icon: 'arrow-left',
    rightAction1Icon: 'more-horizontal',
    rightAction2Icon: 'close',
    name: id || '',
    maxWidth: '',
  };
  return { key, label: key, type: 'text', value: defaultValue !== undefined ? defaultValue : (textDefaults[key] !== undefined ? textDefaults[key] : '') };
}

function createName(id) {
  const item = allItems.find((entry) => entry.id === id);
  return item ? item.name.split(' ')[0] : id;
}

function createDetail(id) {
  const item = allItems.find((entry) => entry.id === id);
  const previewId = previewIdFor(id);
  const hasPreview = Boolean(item && item.previewId);
  const shadcnEntry = shadcnEntryFor(id);
  const base = defaultDetails[previewId] || {};
  const copy = shadcnEntry
    ? [shadcnEntry.note, `shadcn/ui ${shadcnEntry.status} · ${shadcnEntry.trigger}`]
    : componentCopy[previewId] || ['已进入组件库规划，等待 API 和视觉状态确认。', '待补充'];
  const name = item ? item.name : id;
  return {
    id,
    title: base.title || name,
    summary: base.summary || componentSummaries[previewId] || '查看组件的真实效果与用法。',
    desc: base.desc || copy[0],
    status: item ? item.status : 'planned',
    kind: item ? item.kind : 'component',
    groupTitle: item ? item.group.title : 'Component',
    groupKey: item ? item.group.key : 'component',
    path: base.path || (shadcnEntry && !hasPreview ? 'docs/SHADCN_COMPATIBILITY.md' : `poemui-miniprogram/${previewId}/${previewId}`),
    states: base.states || copy[1],
    props: shadcnEntry && !hasPreview
      ? []
      : apiPropsByComponent[previewId] ? makeApiProps(previewId) : base.props || makeDefaultProps(previewId),
    propGroups: apiPropGroupsByComponent[previewId] || [],
    events: apiEventsByComponent[previewId] || [],
    slots: apiSlotsByComponent[previewId] || [],
    methods: apiMethodsByComponent[previewId] || [],
    previewId: previewId === id ? null : previewId,
    shadcnStatus: shadcnEntry ? shadcnEntry.status : null,
    shadcnTrigger: shadcnEntry ? shadcnEntry.trigger : null,
  };
}

function makeDefaultProps(id) {
  const text = allItems.find((item) => item.id === id)?.name.split(' ')[0] || id;
  if (['divider', 'notice-bar', 'result', 'empty'].includes(id)) {
    return [
      { key: 'text', label: 'text', type: 'text', value: text },
      { key: 'theme', label: 'theme', type: 'select', value: 'primary', options: ['primary', 'success', 'warning', 'danger'] },
    ];
  }
  if (['input', 'textarea', 'search'].includes(id)) {
    return [
      { key: 'value', label: 'value', type: 'text', value: id === 'search' ? 'PoemUI 组件' : 'PoemUI' },
      { key: 'status', label: 'status', type: 'select', value: 'default', options: ['default', 'success', 'warning', 'danger'] },
      { key: 'disabled', label: 'disabled', type: 'boolean', value: false },
    ];
  }
  if (['switch', 'checkbox', 'radio'].includes(id)) {
    return [
      { key: 'checked', label: 'checked', type: 'boolean', value: true },
      { key: 'disabled', label: 'disabled', type: 'boolean', value: false },
    ];
  }
  if (['popup', 'action-sheet', 'dropdown-menu'].includes(id)) {
    return [{ key: 'position', label: 'position', type: 'select', value: 'bottom', options: ['bottom', 'top', 'left', 'right'] }];
  }
  if (['progress', 'slider', 'stepper', 'rate', 'count-down'].includes(id)) {
    return [{ key: 'value', label: 'value', type: 'range', value: 64, min: 0, max: 100 }];
  }
  return [
    { key: 'size', label: 'size', type: 'select', value: 'medium', options: ['small', 'medium', 'large'] },
    { key: 'disabled', label: 'disabled', type: 'boolean', value: false },
  ];
}

const themeStorageKey = 'poemui-preview-theme';
const previewPreferencesStorageKey = 'poemui-preview-preferences';
const defaultPreviewPreferences = Object.freeze({
  theme: 'light',
  effectsEnabled: true,
  shadow: 'on',
  frost: 'off',
  radius: 'large',
  gradient: 'off',
  gradientPreset: 'neutral',
  border: 'off',
  equalSpacing: false,
});

const gradientPresetDefinitions = Object.freeze([
  Object.freeze({ value: 'neutral', label: '中性默认' }),
  Object.freeze({ value: 'flowing-gold-pink', label: '流金粉' }),
  Object.freeze({ value: 'premium-black', label: '高级黑' }),
  Object.freeze({ value: 'cement-white', label: '水泥白' }),
  Object.freeze({ value: 'black-gold', label: '黑金' }),
  Object.freeze({ value: 'light-gold', label: '浅金' }),
  Object.freeze({ value: 'ai-mist-blue-violet', label: 'AI 雾蓝紫' }),
  Object.freeze({ value: 'cyber-pink-blue', label: '赛博粉蓝' }),
  Object.freeze({ value: 'aurora-violet', label: '极光紫' }),
]);

function normalizeGradientPreset(value) {
  return gradientPresetDefinitions.some((item) => item.value === value)
    ? value
    : defaultPreviewPreferences.gradientPreset;
}

function readStoredTheme() {
  try {
    const value = window.localStorage.getItem(themeStorageKey);
    return value === 'dark' || value === 'light' ? value : 'light';
  } catch (error) {
    return 'light';
  }
}

function storeTheme(value) {
  if (value !== 'dark' && value !== 'light') return;
  try {
    window.localStorage.setItem(themeStorageKey, value);
  } catch (error) {
    // Storage may be unavailable in private or restricted browser contexts.
  }
}

function normalizePreviewPreferences(value) {
  const source = value && typeof value === 'object' ? value : {};
  return {
    theme: source.theme === 'dark' || source.theme === 'light' ? source.theme : defaultPreviewPreferences.theme,
    effectsEnabled: true,
    shadow: source.shadow === 'on' || source.shadow === 'off' ? source.shadow : defaultPreviewPreferences.shadow,
    frost: source.frost === 'on' || source.frost === 'off' ? source.frost : defaultPreviewPreferences.frost,
    radius: source.radius === 'large' || source.radius === 'normal' ? source.radius : defaultPreviewPreferences.radius,
    gradient: source.gradient === 'on' || source.gradient === 'off' ? source.gradient : defaultPreviewPreferences.gradient,
    gradientPreset: normalizeGradientPreset(source.gradientPreset),
    border: source.border === 'on' || source.border === 'off' ? source.border : defaultPreviewPreferences.border,
    equalSpacing: typeof source.equalSpacing === 'boolean' ? source.equalSpacing : defaultPreviewPreferences.equalSpacing,
  };
}

function readStoredPreviewPreferences() {
  const fallback = { ...defaultPreviewPreferences, theme: readStoredTheme() };
  try {
    const raw = window.localStorage.getItem(previewPreferencesStorageKey);
    if (!raw) return fallback;
    return normalizePreviewPreferences({ ...fallback, ...JSON.parse(raw) });
  } catch (error) {
    return fallback;
  }
}

function storePreviewPreferences(value) {
  const normalized = normalizePreviewPreferences(value);
  storeTheme(normalized.theme);
  try {
    window.localStorage.setItem(previewPreferencesStorageKey, JSON.stringify(normalized));
  } catch (error) {
    // Storage may be unavailable in private or restricted browser contexts.
  }
}

