function resolveChecked(props, fallbackKey) {
  if (props.value !== undefined && props.value !== null) return Boolean(props.value);
  if (props.checked !== undefined && props.checked !== null) return Boolean(props.checked);
  return Boolean(props[fallbackKey]);
}

function normalizePreviewRange(value, min, max, step, integer) {
  let lower = Number(min);
  let upper = Number(max);
  let increment = Math.abs(Number(step));
  let next = Number(value);
  if (!Number.isFinite(lower)) lower = 0;
  if (!Number.isFinite(upper) || upper < lower) upper = lower;
  if (!Number.isFinite(increment) || increment <= 0) increment = 1;
  if (integer) increment = Math.max(1, Math.round(increment));
  if (!Number.isFinite(next)) next = lower;
  next = Math.min(upper, Math.max(lower, next));
  next = lower + Math.round((next - lower) / increment) * increment;
  if (integer) next = Math.round(next);
  return Number(Math.min(upper, Math.max(lower, next)).toFixed(8));
}

function catalogSectionTitleFor(group, item) {
  return (group.sections || []).find((section) => section.items.some((entry) => entry.id === item.id))?.title || '';
}

function catalogVariantLabelFor(item) {
  if (!item.variantOf) return '';
  const parent = allItems.find((candidate) => (candidate.taxonomyId || candidate.packageId || candidate.id) === item.variantOf);
  const parentName = parent?.nameEn || parent?.name || item.variantOf;
  return `${parentName} 变体`;
}

function renderGroups() {
  const root = document.querySelector('#componentGroups');
  const query = state.search.trim().toLowerCase();
  root.innerHTML = groups
    .map((group) => {
      const matchesQuery = (item) => {
        const text = `${item.id} ${item.nameEn || item.name} ${item.nameZh || ''} ${catalogVariantLabelFor(item)} ${group.title} ${catalogSectionTitleFor(group, item)}`.toLowerCase();
        return !query || text.includes(query);
      };
      const items = group.items.filter(matchesQuery);
      if (!items.length) return '';
      const renderItems = (sourceItems) => sourceItems
        .filter(matchesQuery)
        .map((item) => {
          const active = item.id === state.current;
          const name = item.nameEn || item.name;
          const feedbackOrdinal = feedbackOrdinalFor(item.id);
          const variantLabel = catalogVariantLabelFor(item);
          const translation = item.nameZh
            ? `<span class="component-item__translation">${escapeHtml(item.nameZh)}</span>`
            : '';
          return buttonSample({
            previewContract: true,
            customClass: `component-item ${active ? 'is-active' : ''}`,
            variant: 'text',
            size: 'small',
            block: true,
            content: '',
            defaultSlot: `<span class="component-item__feedback-index" aria-hidden="true">${feedbackOrdinal}</span><span class="component-item__name">${escapeHtml(name)}</span>${translation}${variantLabel ? `<span class="component-item__variant">${escapeHtml(variantLabel)}</span>` : ''}`,
            ariaLabel: `第 ${feedbackOrdinal} 号 ${name} ${item.nameZh}${variantLabel ? `，${variantLabel}` : ''}`,
            ariaCurrent: active ? 'page' : '',
            dataAttributes: { id: item.id, 'catalog-order': feedbackOrdinal },
          });
        })
        .join('');
      const body = Array.isArray(group.sections) && group.sections.length
        ? group.sections.map((section) => {
          const sectionItems = renderItems(section.items);
          if (!sectionItems) return '';
          const sectionId = `component-group-${group.key}-${section.key}`;
          return `<section class="component-group__section" aria-labelledby="${escapeHtml(sectionId)}"><h3 id="${escapeHtml(sectionId)}" class="component-group__section-title">${escapeHtml(section.title)}</h3>${sectionItems}</section>`;
        }).join('')
        : renderItems(group.items);
      return `
        <section class="component-group">
          <h2 class="component-group__title"><span>${group.title}</span>${badgeSample({ count: items.length, size: 'small', standalone: true, ariaLabel: `${group.title} ${items.length} 项` })}</h2>
          ${body}
        </section>
      `;
    })
    .join('');
}

function globalSearchResults() {
  const query = state.globalSearchQuery.trim().toLowerCase();
  const tokens = query.split(/\s+/).filter(Boolean);
  const matches = allItems
    .map((item) => {
      const text = `${item.id} ${item.nameEn || item.name} ${item.nameZh || ''} ${catalogVariantLabelFor(item)} ${item.group.title} ${catalogSectionTitleFor(item.group, item)}`.toLowerCase();
      if (tokens.some((token) => !text.includes(token))) return null;
      const nameEn = String(item.nameEn || item.name || '').toLowerCase();
      const nameZh = String(item.nameZh || '').toLowerCase();
      const score = !query ? 0 : nameEn === query || nameZh === query || item.id === query ? 3 : nameEn.startsWith(query) || nameZh.startsWith(query) ? 2 : 1;
      return { item, score };
    })
    .filter(Boolean);
  return groups.flatMap((group) => matches
    .filter((entry) => entry.item.group.key === group.key)
    .sort((left, right) => right.score - left.score || left.item.name.localeCompare(right.item.name, 'zh-CN'))
    .map((entry) => entry.item));
}

function renderGlobalSearchDialog() {
  const mount = document.querySelector('#globalSearchMount');
  if (!mount) return;
  if (!state.globalSearchOpen) {
    mount.innerHTML = '';
    return;
  }
  const results = globalSearchResults();
  state.globalSearchActiveIndex = results.length ? Math.max(0, Math.min(results.length - 1, state.globalSearchActiveIndex)) : 0;
  let resultIndex = 0;
  const resultGroups = groups.map((group) => {
    const items = results.filter((item) => item.group.key === group.key);
    if (!items.length) return '';
    const itemMarkup = items.map((item) => {
      const index = resultIndex;
      resultIndex += 1;
      const active = index === state.globalSearchActiveIndex;
      return buttonSample({
        previewContract: true,
        customClass: `global-search-result ${active ? 'is-active' : ''}`,
        variant: 'text',
        size: 'small',
        block: true,
        content: '',
        icon: item.kind === 'document' ? 'file-text' : item.kind === 'guide' ? 'compass' : 'component',
        defaultSlot: `<span class="global-search-result__copy"><strong>${escapeHtml(item.nameEn || item.name)}</strong><small>${escapeHtml(item.nameZh || group.title)}</small></span>`,
        suffix: `<span class="global-search-result__group">${escapeHtml(group.title)}</span>`,
        role: 'option',
        ariaSelected: active,
        ariaLabel: `${item.nameEn || item.name} ${item.nameZh || ''}，${group.title}`,
        dataAttributes: { 'global-search-id': item.id, 'global-search-index': index },
      });
    }).join('');
    return `<section class="global-search-group" aria-label="${escapeHtml(group.title)}"><h3>${escapeHtml(group.title)}</h3>${itemMarkup}</section>`;
  }).join('');
  const empty = results.length ? '' : `<div class="global-search-empty">${emptySample({ embedded: true, description: '试试组件英文名、中文名或分类', icon: 'search', ariaLabel: '没有匹配的组件' })}</div>`;
  mount.innerHTML = `<div class="global-search-overlay" data-global-search-overlay>
    <section class="global-search-dialog pui-dialog" role="dialog" aria-modal="true" aria-labelledby="globalSearchTitle" aria-describedby="globalSearchDescription">
      <header class="global-search-dialog__header">
        <span class="global-search-dialog__header-slot" aria-hidden="true"></span>
        <span class="global-search-dialog__heading"><strong id="globalSearchTitle">快速抵达</strong><small id="globalSearchDescription">搜索 PoemUI 组件与规范</small></span>
        ${iconButtonSample({ icon: 'close', customClass: 'global-search-close', ariaLabel: '关闭快速搜索', title: '关闭快速搜索', dataAttributes: { 'global-search-close': true } })}
      </header>
      <div class="global-search-dialog__content">
        ${inputControlSample({ id: 'globalSearchInput', customClass: 'global-search-input', type: 'search', size: 'medium', prefixIcon: 'search', value: state.globalSearchQuery, placeholder: '输入组件名、中文名或分类', autocomplete: 'off', ariaLabel: '搜索 PoemUI 组件与规范' })}
        <div id="globalSearchResults" class="global-search-results" role="listbox" aria-label="搜索结果">${resultGroups}${empty}</div>
      </div>
      <footer class="global-search-dialog__footer" aria-label="键盘操作提示"><span>↑↓ 选择</span><span>Enter 打开</span><span>Esc 关闭</span></footer>
    </section>
  </div>`;
  requestAnimationFrame(() => {
    const input = document.querySelector('#globalSearchInput');
    if (!input) return;
    input.focus({ preventScroll: true });
    input.setSelectionRange(input.value.length, input.value.length);
    document.querySelector('.global-search-result.is-active')?.scrollIntoView({ block: 'nearest' });
  });
}

function openGlobalSearch() {
  setAppearanceMenuOpen(false);
  if (!state.globalSearchOpen) state.globalSearchReturnFocus = document.activeElement;
  state.globalSearchOpen = true;
  state.globalSearchQuery = '';
  const results = globalSearchResults();
  state.globalSearchActiveIndex = Math.max(0, results.findIndex((item) => item.id === state.current));
  document.body.classList.add('is-global-search-open');
  renderGlobalSearchDialog();
}

function closeGlobalSearch(restoreFocus = true) {
  if (!state.globalSearchOpen) return;
  const returnFocus = state.globalSearchReturnFocus;
  state.globalSearchOpen = false;
  state.globalSearchQuery = '';
  state.globalSearchActiveIndex = 0;
  state.globalSearchReturnFocus = null;
  document.body.classList.remove('is-global-search-open');
  renderGlobalSearchDialog();
  if (restoreFocus && returnFocus && returnFocus.isConnected && typeof returnFocus.focus === 'function') returnFocus.focus({ preventScroll: true });
}

function chooseGlobalSearchResult() {
  const result = globalSearchResults()[state.globalSearchActiveIndex];
  if (!result) return;
  closeGlobalSearch(false);
  selectComponent(result.id, true);
}

