const previewPreferenceDefinitions = [
  { key: 'border', label: '边框', ariaLabel: '边框' },
  { key: 'shadow', label: '阴影', ariaLabel: '阴影' },
  { key: 'frost', label: '毛玻璃', ariaLabel: '毛玻璃' },
  { key: 'radius', label: '大圆角', ariaLabel: '大圆角' },
  { key: 'gradient', label: '渐变', ariaLabel: '渐变背景' },
  { key: 'equalSpacing', label: '间距相等', ariaLabel: '间距相等' },
  { key: 'theme', label: '深色', ariaLabel: '深色模式' },
];

function previewPreferenceChecked(key) {
  if (key === 'theme') return state.theme === 'dark';
  if (key === 'radius') return state.radius === 'large';
  if (key === 'equalSpacing') return state.equalSpacing === true;
  return state[key] === 'on';
}

const previewAppearancePresets = Object.freeze({
  standard: Object.freeze({ effectsEnabled: true, shadow: 'on', frost: 'off', radius: 'large', border: 'off', gradient: 'off', gradientPreset: 'neutral' }),
  fruit: Object.freeze({ effectsEnabled: true, shadow: 'on', frost: 'on', radius: 'large', border: 'off', gradient: 'off', gradientPreset: 'neutral' }),
});

function previewAppearanceMatches(presetName) {
  const preset = previewAppearancePresets[presetName];
  if (!preset) return false;
  return Object.entries(preset).every(([key, value]) => state[key] === value);
}

function applyPreviewAppearancePreset(presetName) {
  const preset = previewAppearancePresets[presetName];
  if (!preset) return false;
  Object.assign(state, preset);
  storePreviewPreferences(state);
  renderAll();
  return true;
}

