      <header class="appearance-menu__header"><strong id="appearanceMenuTitle">外观</strong>${iconButtonSample({ id: 'appearanceResetAction', icon: 'refresh', size: 'small', shape: 'circle', theme: 'primary', variant: 'base', ariaLabel: '重置外观设置', title: '重置外观设置', dataAttributes: { 'appearance-reset': true } })}</header>
