function syncAppearanceMenu() {
  const root = document.querySelector('[data-appearance-menu]');
  const trigger = document.querySelector('#appearanceMenuTrigger');
  const panel = document.querySelector('#appearanceMenuPanel');
  if (!root || !trigger || !panel) return;
  root.classList.toggle('is-open', state.appearanceMenuOpen);
  trigger.setAttribute('aria-expanded', String(state.appearanceMenuOpen));
  trigger.setAttribute('aria-label', state.appearanceMenuOpen ? '关闭外观设置' : '打开外观设置');
  panel.setAttribute('aria-hidden', String(!state.appearanceMenuOpen));
  panel.inert = !state.appearanceMenuOpen;
  syncFruitFlavorControl();
}

function syncFruitFlavorControl() {
  const root = document.querySelector('[data-fruit-flavor-control] [data-switch-root]');
  const control = root?.querySelector('[role="switch"]');
  if (!root || !control) return;
  const checked = previewAppearanceMatches('fruit');
  root.classList.toggle('is-checked', checked);
  control.setAttribute('aria-checked', String(checked));
  control.title = checked ? '果味配置：已开启' : '果味配置：已关闭';
}

function setAppearanceMenuOpen(open, restoreFocus = false) {
  const nextOpen = !!open;
  if (state.appearanceMenuOpen === nextOpen) return;
  state.appearanceMenuOpen = nextOpen;
  syncAppearanceMenu();
  if (nextOpen) {
    requestAnimationFrame(() => document.querySelector('#appearanceMenuPanel [role="switch"]')?.focus({ preventScroll: true }));
  } else if (restoreFocus) {
    document.querySelector('#appearanceMenuTrigger')?.focus({ preventScroll: true });
  }
}

