  const defaultSlot = props.defaultSlot !== undefined ? String(props.defaultSlot) : (label === '' ? '' : escapeHtml(label));
  const renderedDefaultSlot = iconOnly ? '' : defaultSlot;
  const formType = ['submit', 'reset'].includes(props.formType) ? props.formType : 'button';
  const platformOpenType = locked ? '' : String(props.openType || '');
  const customStyle = typeof props.customStyle === 'string' ? props.customStyle : '';
  return `<button class="${classes}" type="${formType}" lang="${escapeHtml(['en', 'zh_CN', 'zh_TW'].includes(props.lang) ? props.lang : 'en')}" data-open-type="${escapeHtml(platformOpenType)}" data-form-type="${locked ? '' : escapeHtml(props.formType || '')}" data-session-from="${escapeHtml(props.sessionFrom || '')}" data-send-message-title="${escapeHtml(props.sendMessageTitle || '')}" data-send-message-path="${escapeHtml(props.sendMessagePath || '')}" data-send-message-img="${escapeHtml(props.sendMessageImg || '')}" data-show-message-card="${!!props.showMessageCard}" data-app-parameter="${escapeHtml(props.appParameter || '')}" data-hover-class="${escapeHtml(props.hoverClass || 'none')}" data-hover-stop-propagation="${!!props.hoverStopPropagation}" data-phone-number-no-quota-toast="${props.phoneNumberNoQuotaToast !== false}" data-activity-type="${escapeHtml(props.activityType ?? '')}" data-entrance-path="${escapeHtml(props.entrancePath || '')}" data-need-show-entrance="${props.needShowEntrance !== false}" style="--pui-button-hover-start:${hoverStart}ms;--pui-button-hover-stay:${hoverStay}ms;--pui-button-duration:${props.reduceMotion ? '1ms' : 'var(--pui-duration-normal)'};--pui-button-ease:${props.reduceMotion ? 'linear' : 'var(--pui-ease-standard)'};${escapeHtml(customStyle)}"${attrs}>${spinner}${leading}<span class="pui-button-preview__content">${renderedDefaultSlot}</span>${suffix}</button>`;
