// FAB 是 Button 家族的轻量浮动操作表面：位置由父级决定，视觉与交互仍复用唯一的 Button 镜像。
function fabSample(props = {}) {
  const theme = ['default', 'primary', 'danger', 'inverse'].includes(props.theme) ? props.theme : 'default';
  const variant = ['base', 'outline', 'text', 'ghost', 'transparent'].includes(props.variant) ? props.variant : 'base';
  const size = ['extra-small', 'small', 'medium', 'large'].includes(props.size) ? props.size : 'medium';
  const content = props.content === undefined ? '' : String(props.content);
  const classes = [
    'pui-fab-preview',
    `pui-fab-preview--${theme}`,
    props.customClass || '',
    content ? 'is-extended' : '',
    props.loading ? 'is-loading' : '',
    props.disabled ? 'is-disabled' : '',
    props.reduceMotion ? 'is-reduced-motion' : '',
  ].filter(Boolean).join(' ');
  return `<span class="${classes}">${buttonSample({
    previewContract: true,
    customClass: 'pui-fab-preview__button',
    theme: theme === 'inverse' ? 'default' : theme,
    variant,
    size,
    shape: content ? 'round' : 'circle',
    icon: String(props.icon || ''),
    iconOnly: !content,
    content,
    loading: !!props.loading,
    disabled: !!props.disabled,
    ariaLabel: props.ariaLabel || content || '浮动操作',
    reduceMotion: !!props.reduceMotion,
    demoAction: props.demoAction,
    dataAttributes: props.dataAttributes,
  })}</span>`;
}

