    id: `${controlKey}Trigger`,
    previewContract: true,
    customClass: 'pui-select-control__trigger',
    variant: 'outline',
    size: size === 'extra-small' ? 'extra-small' : 'small',
    content: selectedOption?.label || props.placeholder || '请选择',
    suffix: `<span class="pui-select-control__icon" aria-hidden="true">${iconComponent('chevron-down', { pxSize: size === 'extra-small' ? 14 : 16 })}</span>`,
    role: 'combobox',
    ariaLabel: semanticLabel,
    ariaExpanded: false,
    ariaHaspopup: 'listbox',
