    <article class="pui-showcase-section"><h3>卡片与 Generic</h3><div class="pui-collapse-preview__actions">${buttonSample({ content: props.theme === 'card' ? '默认分组' : '卡片主题', icon: 'layers', size: 'small', variant: 'outline', disabled: !!props.disabled, demoAction: 'collapse-toggle-theme' })}${buttonSample({ content: props.customPanel ? '默认内容' : 'Generic 内容', icon: 'component', size: 'small', variant: 'outline', disabled: !!props.disabled, demoAction: 'collapse-toggle-generic' })}${buttonSample({ content: props.expandIcon === false ? '显示箭头' : '隐藏箭头', icon: 'chevron-down', size: 'small', variant: 'text', disabled: !!props.disabled, demoAction: 'collapse-toggle-icon' })}</div></article>
