  const duration = previewMotionDuration(props.duration, props.reduceMotion);
  const easingFunction = ['default', 'linear', 'easeInCubic', 'easeOutCubic', 'easeInOutCubic'].includes(props.easingFunction) ? props.easingFunction : 'default';
  const easing = { default: 'var(--ease-standard)', linear: 'linear', easeInCubic: 'cubic-bezier(.55,.055,.675,.19)', easeOutCubic: 'cubic-bezier(.215,.61,.355,1)', easeInOutCubic: 'cubic-bezier(.645,.045,.355,1)' }[easingFunction];
  const multiple = Math.min(Math.max(1, items.length || 1), Math.max(1, Math.min(5, Math.round(Number(props.displayMultipleItems) || 1))));
