  const tag = item.tag ? tagSample({ theme: item.tagTheme, variant: 'light', size: 'small', content: item.tag }) : '';
  return `${visual}<div class="pui-swiper-preview__scrim"></div><div class="pui-swiper-preview__copy">${tag}<strong>${escapeHtml(item.title)}</strong>${item.description ? `<span>${escapeHtml(item.description)}</span>` : ''}</div>`;
