    const currentProps = getProps(state.current);
    const currentDemo = getDemoState('swiper');
    const current = swiperPreviewSnapshot(currentProps, currentDemo);
    commitSwiperPreview(currentProps, currentDemo, current.index + 1, 'autoplay');
    scheduleSwiperPreviewAutoplay(currentProps, currentDemo);
