  const dateOnly = dateTimePickerH5Model(dateOnlyProps, {});
  const timeOnlyProps = dateTimePreviewStatic({ defaultValue: '09:30:40', mode: 'second', start: '09:00:00', end: '18:00:00', format: 'HH:mm:ss', title: '选择时间' });
  const timeOnly = dateTimePickerH5Model(timeOnlyProps, {});
  const stepProps = dateTimePreviewStatic({ defaultValue: '2026-07-15 09:30', mode: ['date', 'minute'], start: '2026-07-15 09:00', end: '2026-07-15 12:00', steps: { minute: 15 }, showWeek: true, title: '发布窗口' });
  const step = dateTimePickerH5Model(stepProps, {});
  const disabledProps = dateTimePreviewStatic({ defaultValue: '2026-07', mode: 'month', disabled: true, title: '禁用月份' });
  const disabled = dateTimePickerH5Model(disabledProps, {});
